/*
 * A235726  Lexicographically earliest sequence of positive integers such that
 *          a(nm) != a(n + m) for all positive integers n and m such that nm
 *          != n + m.
 * https://oeis.org/A235726
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   The sequence is generated by lexicographically earliest
 *            assignment: a(1)=1, a(n) is the smallest positive integer not
 *            equal to a(m) for any m < n such that n = m*k or n = m + k (with
 *            m*k ≠ m + k). This implements the greedy graph‑coloring
 *            described in the OEIS entry for A235726
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

/* External types supplied by the build */
extern seq_t a(idx_t n);

static seq_t *cache      = NULL;     /* computed values */
static idx_t cache_size  = 0;        /* number of filled entries */
static size_t cap        = 0;        /* allocated array size */

static uint64_t *color_mark = NULL;  /* tick marks for used colors */
static size_t   mark_size   = 0;     /* allocated size of color_mark */
static uint64_t tick        = 1;     /* current tick value */

/* enlarge cache to hold at least n elements */
static void ensure_size(idx_t n)
{
    if ((size_t)n <= cap)
        return;
    size_t new_cap = n * 2;
    if (new_cap < (size_t)n)
        new_cap = (size_t)n;
    seq_t *tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) abort();
    cache = tmp;
    cap   = new_cap;
    /* also enlarge color_mark if needed */
    if (new_cap + 2 > mark_size) {
        size_t new_sz = (new_cap + 2) * 2;
        uint64_t *m = (uint64_t*)realloc(color_mark, new_sz * sizeof(uint64_t));
        if (!m) abort();
        /* zero new entries */
        for (size_t i = mark_size; i < new_sz; ++i)
            m[i] = 0;
        color_mark = m;
        mark_size  = new_sz;
    }
}

/* main function required by the test harness */
seq_t a(idx_t n)
{
    if (n == 0) return 0;  /* undefined for n<1, safety */

    if (n <= cache_size)
        return cache[n - 1];

    /* grow workspace */
    ensure_size(n);

    /* build values for indices cache_size+1 .. n */
    for (idx_t idx = cache_size + 1; idx <= n; ++idx) {
        idx_t i = idx; /* 1‑based */

        /* mark colors of already computed neighbors */
        if (tick == (uint64_t)-1) {          /* avoid overflow */
            for (size_t j = 0; j < mark_size; ++j)
                color_mark[j] = 0;
            tick = 1;
        }
        ++tick;  /* new tick for this index */

        /* ----- neighbors from factor pairs ---- */
        for (idx_t d = 1; d * d <= i; ++d) {
            if (i % d != 0) continue;
            idx_t e = i / d;
            if (d + e != i) {           /* ensure nm != n+m */
                idx_t j = d + e;        /* neighbor index */
                if (j < i && j >= 1) {
                    seq_t col = cache[j - 1];
                    if ((size_t)col < mark_size)
                        color_mark[(size_t)col] = tick;
                }
            }
        }

        /* ----- neighbors from sum pairs ---- */
        for (idx_t m = 1; m < i; ++m) {
            idx_t prod = m * (i - m);
            if (prod == i) continue;   /* skip equal case */
            if (prod < i) {
                seq_t col = cache[prod - 1];
                if ((size_t)col < mark_size)
                    color_mark[(size_t)col] = tick;
            }
        }

        /* find minimal unused color */
        seq_t val = 1;
        for (;;) {
            if ((size_t)val >= mark_size) { /* should not happen, resize */
                size_t new_sz = mark_size * 2;
                uint64_t *m = (uint64_t*)realloc(color_mark, new_sz * sizeof(uint64_t));
                if (!m) abort();
                for (size_t j = mark_size; j < new_sz; ++j) m[j] = 0;
                color_mark = m;
                mark_size  = new_sz;
            }
            if (color_mark[(size_t)val] != tick) break;
            ++val;
        }
        cache[i - 1] = val;
    }
    cache_size = n;
    return cache[n - 1];
}
